let drawing = [];
let currentColor = 0; // 0:黒, 1:赤, 2:青
let strokeWeight = 5;
let isDrawing = false;

function setup() {
  createCanvas(400, 400);
  colorMode(RGB, 255);
  background(255);
}

function draw() {
  background(255);

  // マウスが押されている間だけ線を描く
  if (isDrawing) {
    stroke(drawing[drawing.length - 1].c);
    strokeWeight(strokeWeight);
    line(drawing[drawing.length - 2].x, drawing[drawing.length - 2].y, drawing[drawing.length - 1].x, drawing[drawing.length - 1].y);
    drawing.push(drawing[drawing.length - 1]);
  }

  // 描画をリセットするボタン
  fill(255);
  noStroke();
  rect(300, 30, 100, 30, 5);
  fill(0);
  textAlign(CENTER, CENTER);
  textSize(14);
  text("やりなおし", 350, 40);
}

function mousePressed() {
  if (mouseX > 300 && mouseX < 400 && mouseY > 30 && mouseY < 40) {
    // リセットボタンが押されたら
    drawing = [];
    isDrawing = false;
  } else {
    // 描画開始
    isDrawing = true;
    drawing.push(createPoint(mouseX, mouseY));
  }
}

function mouseDragged() {
  if (isDrawing) {
    drawing.push(createPoint(mouseX, mouseY));
  }
}

function mouseReleased() {
  isDrawing = false;
}

function createPoint(x, y) {
  return { x: x, y: y, c: currentColor };
}
