let numCircles = 10;
let glowColor = color(255, 100, 100);
let circleRadius = 20;

function setup() {
  createCanvas(400, 400);
  background(0);
}

function draw() {
  background(0, 10); // ネオン効果のための暗い背景

  for (let i = 0; i < numCircles; i++) {
    let x = width / numCircles * (i + 0.5);
    let y = height / numCircles * (i + 0.5);
    let c = color(255, 100, 100, 255 - i * 15); // 透明度を少しずつ上げる

    noStroke();
    fill(c);
    ellipse(x, y, circleRadius, circleRadius);

    // グロー効果
    fill(c, 100);
    ellipse(x + 5, y + 5, circleRadius + 5, circleRadius + 5);
  }
}
