  { question: "日本の首都はどこ？", options: ["大阪", "東京", "名古屋"], answer: "東京" },
  { question: "太陽系の惑星はいくつある？", options: ["7つ", "8つ", "9つ"], answer: "8つ" },
  { question: "水が凍る状態を何というか？", options: ["蒸気", "液体", "固体"], answer: "固体" }
];
let currentQuestionIndex = 0;
let correctAnswers = 0;
let totalQuestions = quizData.length;
let quizActive = false;
let feedbackMessage = "";

function setup() {
  createCanvas(500, 600);
  textAlign(CENTER, TOP);
  textSize(20);
  drawQuiz();
}

function drawQuiz() {
  background(240);
  textSize(18);
  fill(0);
  text("クイズ！", width / 2, 30);
  textSize(24);
  fill(0);
  text(quizData[currentQuestionIndex].question, width / 2, height / 2 - 30);
  textSize(16);
  fill(0);
  text("選択肢:", width / 2, height / 2 + 20);
  textSize(18);
  fill(0);
  text(quizData[currentQuestionIndex].options.join(" | "), width / 2, height / 2 + 40);
  textSize(20);
  fill(0, 150, 255);
  text("答え:", width / 2, height / 2 + 70);
}

function drawFeedback() {
  fill(255, 150, 0);
  textSize(22);
  text(feedbackMessage, width / 2, height / 2 + 30);
}

function handleAnswerSelection(selectedIndex) {
  if (!quizActive) {
    feedbackMessage = "まずクイズを始めるボタンを押してください！";
    drawFeedback();
    return;
  }

  let userAnswer = quizData[currentQuestionIndex].options[selectedIndex - 1];
  let correctAnswer = quizData[currentQuestionIndex].answer;

  if (userAnswer === correctAnswer) {
    correctAnswers++;
    feedbackMessage = "正解！🎉";
    fill(0, 150, 0);
    textSize(20);
    text("次へ", width / 2, height / 2 + 50);
    quizActive = false;
  } else {
    feedbackMessage = "不正解...😢";
    fill(255, 0, 0);
    textSize(20);
    text("もう一度試そう！", width / 2, height / 2 + 50);
  }

  // Move to next question or end quiz
  if (currentQuestionIndex < totalQuestions - 1) {
    currentQuestionIndex++;
    quizActive = true;
    drawQuiz();
  } else {
    endQuiz();
  }
}

function startQuiz() {
  currentQuestionIndex = 0;
  quizActive = true;
  feedbackMessage = "クイズ開始！";
  quizActive = false; // Disable buttons until quiz is ready
  drawQuiz();
}

