  text("🎉 クイズ終了！ 🎉", width / 2, height / 2);
  textSize(18);
  text(`あなたの正解数: ${correctAnswers} / ${totalQuestions}`, width / 2, height / 2 + 40);
  textSize(18);
  text("もう一度始める", width / 2, height - 50);
}

function draw() {
  background(240);

  if (!quizActive) {
    fill(0, 150, 255);
    rect(width / 2 - 100, height / 2 - 30, 200, 50, 10);
    textSize(20);
    text("クイズを始める", width / 2, height / 2 + 35);
  } else {
    drawQuiz();
    drawFeedback();
  }

