let fish = [];
let myScore = 0;
let sparkle = [];

function setup() {
  createCanvas(400, 400);
  background(50);
  for (let i = 0; i < 5; i++) {
    fish.push({ x: random(width), y: random(height), vy: random(-2, 2), size: random(10, 25) });
  }
}

function draw() {
  background(50);

  // キラキラを描画
  for (let i = sparkle.length - 1; i >= 0; i--) {
    let s = sparkle[i];
    s.y -= s.vy;
    s.a -= 0.1;
    if (s.a <= 0) sparkle.splice(i, 1);
    fill(s.c, s.a);
    noStroke();
    ellipse(s.x, s.y, s.s, s.s);
  }

  // 魚を描画
  for (let i = 0; i < fish.length; i++) {
    let f = fish[i];
    fill(255, 150, 50);
    ellipse(f.x, f.y, f.size, f.size);
    stroke(255);
    strokeWeight(f.size / 5);
    line(f.x, f.y, f.x + f.vx, f.y + f.vy);
  }

  // 敵を描画 (画面外からくる)
  if (random() < 0.05) { // 敵が出現する確率
    let e = { x: random(width), y: random(height), vx: random(-1, 1), vy: random(-1, 1), size: random(15, 30) };
    fill(255, 100, 100);
    rect(e.x - e.size/2, e.y - e.size/2, e.size, e.size);
  }

  // 衝突判定とスコア更新
  for (let i = fish.length - 1; i >= 0; i--) {
    let f = fish[i];
    let e = enemies[i];
    if (dist(f.x, f.y, e.x, e.y) < f.size / 2) {
      if (f.vy > 0) { // 魚が上に逃げている
        myScore++;
        sparkle.push({ x: f.x, y: f.y, s: f.size, c: random(255, 200, 100), vy: random(1, 3) });
        fish.splice(i, 1);
        enemies.splice(i, 1);
        break;
      } else { // 魚が下に落ちている
        myScore--;
        sparkle.push({ x: f.x, y: f.y, s: f.size, c: random(255, 200, 100), vy: random(1, 3) });
        fish.splice(i, 1);
        enemies.splice(i, 1);
        break;
      }
    }
  }

  // 魚を画面外に出す
  for (let i = fish.length - 1; i >= 0; i--) {
    let f = fish[i];
    if (f.x < -f.size || f.x > width + f.size || f.y < -f.size || f.y > height + f.size) {
      fish.splice(i, 1);
    }
  }

  // 敵を画面内に留める
  for (let i = 0; i < enemies.length; i++) {
    let e = enemies[i];
    if (e.x < -e.size/2 || e.x > width + e.size/2 || e.y < -e.size/2 || e.y > height + e.size/2) {
      enemies.splice(i, 1);
    }
  }

  // スコア表示
  fill(255);
  textSize(20);
  textAlign(LEFT, TOP);

