  createCanvas(400, 400);
  textAlign(CENTER, BOTTOM);
  textSize(18);
  resetGame();
}

function resetGame() {
  score = 0;
  gameActive = false;
  gameOver = false;
  targetAnimal = null;
  animals = [];
  playerX = width / 2;
  playerY = height - 50;
  spawnAnimal();
}

function draw() {
  background(240);

  if (!gameActive) {
    if (gameOver) {
      fill(255, 100, 100);
      text("ゲームオーバー", width / 2, height / 2);
      textSize(24);
      text("再スタート: スペース", width / 2, height - 50);
    } else {
      fill(0);
      text("動物をタップして目標に！", width / 2, height / 2);
    }
    return;
  }

  // プレイヤー
  fill(0, 150, 0);
  ellipse(playerX, playerY, 30, 40);

  // 目標
  fill(255, 100, 100);
  ellipse(targetX, targetY, 30, 40);

  // 動物
  animals.forEach(animal => {
    fill(animal.color);
    ellipse(animal.x, animal.y, animal.size, animal.height);
    if (animal.isCaught) {
      fill(0);
      rect(animal.x - animal.width / 2, animal.y - animal.height / 2, animal.width, animal.height);
      text(animal.name, animal.x, animal.y);
    }
  });

  // 状態表示
  fill(0);
  text("スコア: " + score, width / 2, 30);
  if (targetAnimal) {
    text("目標: " + targetAnimal.name, width / 2, height / 2 + 30);
  }
}

function spawnAnimal() {
  let choice = floor(random(3));
  if (choice === 0) {
    animals.push({ name: "うさぎ", x: random(50, 250), y: random(50, 300), size: 30, height: 40, isCaught: false, color: random(color(200, 100, 100), color(100, 150, 100), color(100, 100, 150)) });
  } else if (choice === 1) {
    animals.push({ name: "ネコ", x: random(150, 350), y: random(100, 250), size: 35, height: 45, isCaught: false, color: random(color(150, 150, 150), color(100, 100, 150), color(100, 150, 100))) });
  } else {
    animals.push({ name: "くま", x: random(100, 300), y: random(100, 250), size: 40, height: 50, isCaught: false, color: random(color(150, 100, 50), color(100, 150, 100), color(100, 100, 100))) });
  }
  targetAnimal = animals[animals.length - 1];
  gameActive = true;
}

function mousePressed() {
  if (!gameActive) {
    resetGame();
    spawnAnimal();
    return;
  }

