let calendarGridSize = 7;
let daysInMonth = 31;
let currentMonth = 1;
let currentYear = 2024;
let calendarCanvasSize = 400;
let cellSize;
let selectedDay = 1;
let selectedMonth = 1;
let selectedYear = currentYear;

function setup() {
  createCanvas(calendarCanvasSize, calendarCanvasSize);
  cellSize = calendarCanvasSize / calendarGridSize;
  textAlign(CENTER, CENTER);
  textSize(cellSize * 0.6);
  drawCalendar();
}

function drawCalendar() {
  background(240, 248, 255); // Light blue background

  // Draw Day Headers (Sun, Mon, Tue, Wed, Thu, Fri, Sat)
  for (let i = 1; i <= calendarGridSize; i++) {
    let dayOfWeek = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][i % 7];
    let dayOfMonth = i > 7 ? i - 7 : i;
    let isCurrentMonth = (i <= daysInMonth);
    let isCurrentYear = (currentMonth === selectedMonth && currentYear === selectedYear);

    let color = isCurrentMonth && isCurrentYear ? color(255, 200, 200) : color(200, 200, 255);

    fill(color);
    noStroke();
    rect(i * cellSize, 0, cellSize, cellSize);

    if (isCurrentMonth && isCurrentYear) {
      fill(255, 100, 100);
      text(dayOfMonth, i * cellSize + cellSize / 2);
    }
  }
}

function drawSelection() {
  // Draw Selected Month/Year Box
  let monthStart = (selectedMonth - 1) * calendarGridSize;
  let monthEnd = selectedMonth * cellSize;
  let yearStart = selectedYear * calendarGridSize;
  let yearEnd = (selectedYear + 1) * calendarGridSize;

  fill(255, 255, 150, 150); // Light yellow/orange
  stroke(255, 255, 255, 5);
  rect(monthStart, yearStart, monthEnd - yearStart, yearEnd - yearStart);

  // Draw Selected Day Circle
  let dayCol = (selectedDay - 1) % calendarGridSize;
  let dayRow = floor((selectedDay - 1) / calendarGridSize);

  fill(255, 255, 0); // Yellow
  noStroke();
  ellipse(dayCol * cellSize + cellSize / 2, dayRow * cellSize + cellSize / 2, cellSize * 0.7, cellSize * 0.7);
}

function drawScore() {
  fill(0);
  textSize(16);
  text("Score: " + myScore, 10, 25);
}

function drawInstructions() {
  fill(50);
  noStroke();
  textSize(14);
  text("Click a day to select it.", 10, 35);
  text("Click a month/year to select it.", 10, 45);
  text("Click a cell to select it.", 10, 55);
}

