  for (let i = stars.length - 1; i >= 0; i--) {
    let star = stars[i];
    fill(star.r, star.g, star.b);
    noStroke();
    ellipse(star.x, star.y, star.s, star.s);
    if (star.dist(playerX, playerY) > 200) {
      stars.splice(i, 1);
    }
  }

  // 敵（シンプルな四角）
  for (let i = 0; i < 5; i++) {
    let enemy = createEnemy();
    if (enemy.dist(playerX, playerY) < 100) {
      score++;
    }
    enemy.x += enemy.vx;
    enemy.y += enemy.vy;
    if (enemy.x < 0 || enemy.x > width || enemy.y < 0 || enemy.y > height) {
      stars.push(createStar());
    }
  }

  // スコア表示
  fill(255);
  text("Score: " + score, playerX, playerY + 30);

  // スポーン処理
  if (millis() - lastSpawnTime > spawnInterval) {
    spawnStar();
    lastSpawnTime = millis();
  }
}

function createStar() {
  let x = random(0, width);
  let y = random(0, height);
  let r = random(1, 3);
  let s = random(1, 3);
  return { x, y, r, s };
}

function createEnemy() {
  let x = random(50, width - 50);
  let y = random(50, height - 50);
  let vx = random(-2, 2);
  let vy = random(-2, 2);
  let c = color(random(255), random(255), random(255));
  return { x, y, w: 20, h: 20, vx, vy, c };
}

function keyPressed() {
  if (!gameActive && keyCode === 32) { // Spacebar
    gameActive = true;
    playerX = width / 2;
    playerY = height / 2;
    stars = [];
    score = 0;
    spawnStar();
  }
}

function spawnStar() {
  stars.push(createStar());
  lastSpawnTime = millis();
}
