    let fruit = fruits[i];
    fill(fruit.color);
    noStroke();
    if (fruit.type === 'apple') {
      ellipse(fruit.x, fruit.y, 30, 30);
      fill(255);
      text('🍎', fruit.x - 10, fruit.y + 10);
    } else if (fruit.type === 'banana') {
      rect(fruit.x - 15, fruit.y - 15, 30, 25);
      fill(255);
      text('🍌', fruit.x - 10, fruit.y + 5);
    } else if (fruit.type === 'strange') {
      triangle(fruit.x, fruit.y, fruit.x + 10, fruit.y + 10, fruit.x + 5, fruit.y + 15);
      fill(fruit.color);
      text('👽', fruit.x + 5, fruit.y + 10);
    }
    fruits.splice(i, 1); // 食べたフルーツを削除
  }

  // ゲームオーバー判定 (例: 画面下端に危険なフルーツがある場合)
  for (let i = 0; i < fruits.length; i++) {
