    if (fruit.type === 'poison') {
      if (fruit.y + fruit.size > height - 20) {
        gameOver = true;
        return;
      }
    }
  }

  // ゲームオーバー画面の描画（フルーツがない場合など）
  if (fruits.length === 0 && gameActive) {
    textAlign(CENTER, CENTER);
    textSize(30);
    fill(255, 100, 100);
    text("No Fruits Left!", width / 2, height / 2);
  }
}

function spawnFruits() {
  for (let i = 0; i < 5; i++) {
    let type = ['apple', 'banana', 'strange', 'poison'][i % 4];
    let x = random(50, width - 50);
    let y = random(50, height - 50);
    let size = (type === 'apple') ? 30 : 25;
    let color = (type === 'apple') ? color(255, 200, 200) : (type === 'banana') ? color(255, 255, 150) : (type === 'strange') ? color(100, 150, 255) : color(255, 100, 100);
    fruits.push({ x, y, type, color, size });
  }
  gameActive = true;
}

function keyPressed() {
  if (key === ' ' && !gameActive && !gameOver) {
    spawnFruits();
  }
}
