  noStroke();
  ellipse(balloonX, balloonY, balloonSize, balloonSize);

  // グロー効果
  fill(255, 255, 255, glowAlpha * 0.5);
  ellipse(balloonX + 10, balloonY + 10, balloonSize * 0.8, balloonSize * 0.8);

  // 尾
