  stroke(255, 255, 255, glowAlpha * 0.5);
  strokeWeight(5);
  line(balloonX - 10, balloonY + 10, balloonX - 5, balloonY + 15);
  line(balloonX - 15, balloonY + 20, balloonX - 10, balloonY + 25);

  // 浮力
  balloonVY = balloonVY + 0.3;
  balloonY = balloonY + balloonVY;

  // 画面外に出たら止める
  if (balloonY > height + 20 || balloonY < 0) {
    balloonVY = 0;
  }
  if (balloonX < 0 || balloonX > width) {
    balloonVX = 0;
