let fish = [];
let myScore = 0;
let gameActive = false;
let targetColor;

function setup() {
  createCanvas(400, 400);
  myScore = 0;
  gameActive = false;
  targetColor = color(random(255), random(255), random(255));

  // 魚をいくつか生成
  for (let i = 0; i < 5; i++) {
    fish.push({
      x: random(0, width),
      y: random(0, height),
      vy: random(-2, 2),
      size: random(10, 25),
      color: color(random(255), random(255), random(255))
    });
  }
  textAlign(CENTER, BOTTOM);
  textSize(18);
}

function draw() {
  background(240);

  if (!gameActive) {
    fill(0);
    text("スタート！", width / 2, height / 2);
    return;
  }

  // 魚を動かす
  for (let i = fish.length - 1; i >= 0; i--) {
    let f = fish[i];
    f.y += f.vy;

    // 画面外に出たら消す
    if (f.y < -f.size || f.y > height + f.size) {
      fish.splice(i, 1);
      continue;
    }

    // 目が魚の真ん中に向くように調整
    let targetY = f.y;
    let angle = atan2(targetY - f.y, f.x - mouseX);
    f.vx += cos(angle) * 0.1;
    f.vy += sin(angle) * 0.1;

    // 魚の動きを少しランダムにする
    f.vx += random(-0.1, 0.1);
    f.vy += random(-0.1, 0.1);

    // マウスに近づくようにする
    let dist = dist(f.x, f.y, mouseX, mouseY);
    if (dist > 10) {
      f.vx += (mouseX - f.x) / dist * 0.05;
      f.vy += (mouseY - f.y) / dist * 0.05;
    }

    // マウスに触れたら捕まえる
    if (dist < f.size) {
      myScore++;
      fish.splice(i, 1);
      // 新しい魚を出す
      fish.push({
        x: random(0, width),
        y: random(0, height),
        vy: random(-2, 2),
        size: random(10, 25),
        color: color(random(255), random(255), random(255))
      });
      break; // 描画ループを抜ける
    }
  }

  // スコア表示
  fill(0);
  text("スコア: " + myScore, width - 100, 20);

  // 魚を描画
  for (let f of fish) {
    fill(f.color);
    ellipse(f.x, f.y, f.size, f.size);
  }
}

function mousePressed() {
  if (!gameActive) {
    gameActive = true;
    // ターゲット色をランダムに設定
    targetColor = color(random(255), random(255), random(255));
    // ゲーム開始時に魚を再生成
    fish = [];
    for (let i = 0; i < 5; i++) {
      fish.push({
        x: random(0, width),
        y: random(0, height),
        vy: random(-2, 2),
        size: random(10, 25),
        color: color(random(255), random(255), random(255))
      });
    }
  }
}
