let sprouts = [];
let myScore = 0;
let sparkle = { x: width / 2, y: height / 2, size: 5, alpha: 255, vy: 0 };

function setup() {
  createCanvas(400, 400);
  background(240);
  for (let i = 0; i < 10; i++) {
    sprouts.push({ x: random(width), y: height + 50, vy: random(-1, 1) });
  }
}

function draw() {
  background(240);

  // キラキラを描画
  sparkle.alpha -= 0.5;
  if (sparkle.alpha > 0) {
    fill(255, 255, 255, sparkle.alpha);
    noStroke();
    ellipse(sparkle.x, sparkle.y, sparkle.size, sparkle.size);
    sparkle.vy = 0; // 速度をリセット
  }

  // 新しい芽を出現させる
  if (random(100) < 1) {
    sprouts.push({ x: random(width), y: height + random(50, 150), vy: random(-1, 1) });
  }

  // 芽を更新し、収穫をチェックする
  for (let i = sprouts.length - 1; i >= 0; i--) {
    let sprout = sprouts[i];
    sprout.y += sprout.vy;

    if (sprout.y < height - 50) {
      sprout.y = height - 50;
      sprout.vy = random(-1, 1);
    }

    if (sprout.y > height + 50) {
      sprout.y = height + 50;
      sprout.vy = 0;
      sprout.life = 0;
      sprout.color = color(random(200, 255), random(100, 200), random(100, 200));
      continue;
    }

    // 収穫判定
    if (sprout.life > 10) {
      myScore++;
      sprout.life--;
      sprout.color = color(100, 100, 100); // 収穫されたら灰色に
      sprouts.splice(i, 1);
    }
    sprout.life++;
  }

  // 芽を描画
  for (let i = 0; i < sprouts.length; i++) {
    let sprout = sprouts[i];
    fill(sprout.color);
    noStroke();
    ellipse(sprout.x, sprout.y, 5, 15);
  }

  // スコアとゲームオーバー表示
  fill(0);
  textSize(18);
  text(`Score: ${myScore}`, 10, 30);

  if (sprouts.length === 0 && myScore >= 10) {
    textSize(24);
    textAlign(CENTER, CENTER);
    text("Game Over!", width / 2, height / 2);
  }
}
