  for (let i = sprouts.length - 1; i >= 0; i--) {
    let s = sprouts[i];
    fill(100, 255, 100); // 緑
    rect(s.x, s.y, s.w, s.h);
    s.y += s.vy;
    if (s.y > 370) {
      sprout.push(createSprout());
      sprouts.splice(i, 1);
    }
  }

  // Sprout
  if (sprout) {
    fill(100, 255, 100);
    ellipse(sprout.x, sprout.y, sprout.w, sprout.h);
  }

  // Game Over
  if (enemyX < 0 || enemyX > width || enemyY < 0 || enemyY > height) {
    fill(255, 0, 0);
    text("Game Over", width / 2, height / 2);
    text("Score: " + score, width / 2, height / 2 + 30);
  }
}

