    gameActive = true;
    playerX = width / 2;
    playerY = height - 30;
    enemyX = width - 30;
    enemyY = height - 30;
    enemyVY = -2;
    sprout = createSprout();
  } else if (key === ' ' || key === 'r') { // スペースキーまたは Rキーでリスタート
    resetGame();
  } else if (key === 'q') { // Qキーで終了
    noLoop();
  } else if (key === 'a') { // Aキーで左移動
    playerX = max(10, playerX - 5);
  } else if (key === 'd') { // Dキーで右移動
    playerX = min(width - 20, playerX + 5);
  } else if (key === 'w') { // Wキーでジャンプ
    playerVY = -8;
  }
}

function createSprout() {
  let s = { x: random(10, width - 10), y: 370, w: random(10, 20), h: random(10, 20), vy: 0 };
  sprouts.push(s);
  return s;
}
