    let cloud = clouds[i];
    cloud.y -= cloud.speed;
    cloud.size += 0.1; // くもをだんだんおおきくする

    if (cloud.y < -50) {
      clouds.splice(i, 1); // くもを消す
      continue;
    }

    fill(255, 255, 255, cloud.alpha);
    noStroke();
    ellipse(cloud.x, cloud.y, cloud.size, cloud.size * 1.5);

    // キラキラを描画
    if (sparkleCount > 0) {
      let sparkle = color(255, 255, 255, random(50, 150));
      sparkle.setAlpha(sparkle.alpha - 5);
      stroke(sparkle);
      strokeWeight(2);
      point(sparkle.x, sparkle.y);
      sparkleCount--;
    }
  }

  // 新しいくものをランダムに出現させる
  if (random(1) < 0.5) {
    let newCloud = {
      x: random(0, width),
      y: random(-100, -200),
      speed: random(0.5, 1.5),
      alpha: random(50, 100)
    };
    clouds.push(newCloud);
