let fruits = [];
let score = 0;
let gameActive = false;
let fruitSpeed = 2;

function setup() {
  createCanvas(400, 400);
  textAlign(CENTER, BOTTOM);
  textSize(20);
  startGame();
}

function startGame() {
  gameActive = true;
  score = 0;
  fruits = [];
  spawnFruit();
}

function draw() {
  background(135, 206, 235); // 水色

  if (!gameActive) {
    fill(255);
    text("クリックしてスタート！", width / 2, height / 2);
    return;
  }

  // フルーツを描画
  for (let i = fruits.length - 1; i >= 0; i--) {
    let fruit = fruits[i];
    fill(fruit.color);
    noStroke();
    ellipse(fruit.x, fruit.y, fruit.size, fruit.size);

    // 食べる判定
    if (dist(mouseX, mouseY, pmouseX, pmouseY) < fruit.size / 2) {
      score++;
      fruits.splice(i, 1);
      spawnFruit();
      break; // 描画ループを抜ける
    }
    // 画面外に出たら削除
    if (fruit.x < -fruit.size || fruit.x > width + fruit.size || fruit.y < -fruit.size || fruit.y > height + fruit.size) {
      fruits.splice(i, 1);
    }
  }

  // スコア表示
  fill(0);
  text("Score: " + score, width / 2, 30);

  // ゲームオーバー判定
  if (fruits.length === 0) {
    endGame();
  }
}

function spawnFruit() {
  let fruitType = floor(random(1, 3)); // 1:りんご, 2:バナナ, 3:ぶどう
  let x, y;
  let size = 25;

  if (fruitType === 1) { // りんご
    x = random(50, width - 50);
    y = random(50, height - 50);
    fill(255, 200, 200);
    ellipse(x, y, size, size);
  } else if (fruitType === 2) { // バナナ
    x = random(50, width - 50);
    y = random(50, height - 50);
    fill(255, 255, 150);
    rect(x - size / 2, y - size / 2, size, size);
  } else { // ぶどう
    x = random(50, width - 50);
    y = random(50, height - 50);
    fill(100, 150, 100);
    triangle(x, y, x + size / 2, y + size / 2, x - size / 2, y + size / 2);
  }

  fruits.push({ x: x, y: y, color: fruitType * 50 + random(50), size: size, speed: fruitSpeed });
  fruitSpeed += 0.1; // 時間経過でスピードアップ
}

function endGame() {
  gameActive = false;
  fill(255, 100, 100);
  textSize(30);
  text("Game Over!", width / 2, height / 2);
  textSize(18);
  text("Final Score: " + score, width / 2, height / 2 + 40);
}

function mousePressed() {
  if (!gameActive) {
    startGame();
  }
}
