  createCanvas(400, 400);
  textAlign(CENTER, CENTER);
  textSize(cellSize);
  resetGame();
}

function resetGame() {
  ballX = width / 2;
  ballY = height / 2;
  ballVX = random(-4, 4);
  ballVY = random(-4, 4);
  myScore = 0;
  gameActive = true;
}

function draw() {
  background(240);

  if (gameActive) {
    // ボールを動かす
    ballX = ballX + ballVX;
    ballY = ballY + ballVY;

    // 壁との衝突判定
    if (ballX < cellSize) {
      ballX = cellSize;
      ballVX = -ballVX;
    } else if (ballX > width - cellSize) {
      ballX = width - cellSize;
      ballVX = -ballVX;
    }
    if (ballY < cellSize) {
      ballY = cellSize;
      ballVY = -ballVY;
    } else if (ballY > height - cellSize) {
      ballY = height - cellSize;
      ballVY = -ballVY;
    }

    // スコア更新
    if (ballX > width + cellSize || ballX < 0 || ballY > height + cellSize || ballY < 0) {
      // ゲームオーバー条件（ここではシンプルにボールが画面外に出たらゲームオーバー）
      gameOver();
      return;
    }

    // ボールの描画
    fill(255, 100, 100);
    noStroke();
    ellipse(ballX, ballY, cellSize, cellSize);

    // スコアの描画
    fill(0);
    textSize(cellSize);
    text(myScore, width / 2, 30);
  } else {
    // ゲームオーバー画面
    fill(255);
    textSize(cellSize * 1.5);
    text("GAME OVER", width / 2, height / 2 - 20);
    textSize(cellSize);
    text("Press SPACE to Restart", width / 2, height / 2 + 20);
  }
}

function keyPressed() {
  if (key === ' ' || key === 'Space') {
    if (!gameActive) {
      resetGame();
    } else {
      // ゲームオーバー時のみリセット
      resetGame();
    }
  }
}

function gameOver() {
  gameActive = false;
}
