let birds = [];
let playerX = 200;
let playerY = 350;
let score = 0;
let sparkles = [];
let gameActive = false;

function setup() {
  createCanvas(400, 400);
  textAlign(CENTER, BOTTOM);
  textSize(20);
  startGame();
}

function startGame() {
  gameActive = true;
  score = 0;
  playerY = height / 2;
  playerX = width / 2;
  birdSpeed = 3;
  spawnBird();
}

function draw() {
  background(135, 206, 235); // 水色

  if (!gameActive) {
    fill(255);
    text("スタート！", width / 2, height / 2);
    return;
  }

  // プレイヤー
  fill(255, 0, 0);
  noStroke();
  rect(playerX - 10, playerY - 10, 20, 20);

  // 鳥
  for (let i = birds.length - 1; i >= 0; i--) {
    let bird = birds[i];
    fill(255, 255, 255);
    ellipse(bird.x, bird.y, birdSize, birdSize);
    stroke(0);
    strokeWeight(1);
    line(bird.x, bird.y, bird.x + bird.vx, bird.y + bird.vy);

    if (bird.y > height + 20) {
      birds.splice(i, 1);
      score++;
      sparkles.push(new Sparkle(bird.x, bird.y, bird.vx, bird.vy));
    }
  }

  // スコア
  fill(0);
  text("スコア: " + score, width / 2, 30);

  // キラキラ
  for (let i = sparkles.length - 1; i >= 0; i--) {
    sparkles[i].update();
    sparkles[i].draw();
    if (sparkles[i].life <= 0) {
      sparkles.splice(i, 1);
    }
  }
}

function spawnBird() {
  let birdX = random(50, width - 50);
  let birdY = random(50, height - 50);
  let vx = random(-birdSpeed, birdSpeed);
  let vy = random(-birdSpeed, birdSpeed);
  let size = random(15, 25);
  birds.push({ x: birdX, y: birdY, vx: vx, vy: vy, size: size });
}

function keyPressed() {
  if (key === ' ' || key === 'Enter') {
    if (!gameActive) {
      startGame();
    } else {
      // ゲーム中ならスペースキーでプレイヤーを動かす
      if (key === 'a') playerX -= 10;
      if (key === 'd') playerX += 10;
      if (key === 'w') playerY -= 10;
      if (key === 's') playerY += 10;
    }
  }
}

class Sparkle {
  constructor(x, y, vx, vy) {
    this.x = x;
    this.y = y;
    this.vx = vx * random(0.5, 1.5);
    this.vy = vy * random(0.5, 1.5);
    this.life = 30;
    this.size = random(2, 5);
    this.color = color(random(255), random(255), random(255));
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.life--;
    this.size *= 0.95;
    this.color.a *= 0.9;
  }

  draw() {
    noStroke();
    fill(this.color);
    ellipse(this.x, this.y, this.size, this.size);
  }
}
