```js
let rainY = 0;
let rainSpeed = 3;
let raindrops = [];
let myScore = 0;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(240);

  // 雨を降らせる
  if (random() < 0.5) {
    raindrops.push(createRaindrop());
  }

  // 雨を動かす
  for (let i = raindrops.length - 1; i >= 0; i--) {
    let drop = raindrops[i];
    drop.y += drop.vy;

    // 地面に落ちたら消す
    if (drop.y > height) {
      raindrops.splice(i, 1);
      myScore++;
      continue;
    }

    // 画面外に出たら消す
    if (drop.x < 0 || drop.x > width) {
      raindrops.splice(i, 1);
      continue;
    }

    // 描画
    fill(173, 216, 230); // 水色
    noStroke();
    ellipse(drop.x, drop.y, drop.size, drop.size);

    // タップで動かす/つぶす
    if (mouseIsPressed) {
      drop.vy = -drop.vy * 2; // 逆方向に速く動かす
      drop.size *= 0.9; // 少し小さくする
    }
    drop.size *= 0.99; // 少しずつ小さくする
  }
}

function createRaindrop() {
  return {
    x: random(width),
    y: rainY,
    vy: rainSpeed,
    size: random(3, 7)
  };
}
